#!/usr/bin/env python3
"""Writes the proofs of SHA-256's and SHA-1's round constants into src/lib.bats
(sha256#31), between the lines "(* BEGIN generated by scripts/gen-roots.py *)" and
"(* END generated by scripts/gen-roots.py *)".

The constants are defined by roots (FIPS 180-4, 4.2.2 and 4.2.1):
  SHA-256 K_t = the first 32 bits of the fractional part of the cube root of
                the t-th prime, i.e. floor(cbrt(p) * 2^32) mod 2^32;
  SHA-1   K_t = floor(sqrt(n) * 2^30) for n = 2, 3, 5, 10.
A root is a relation on 12-bit limbs, because the solver is 32-bit and a
limb product is under 2^24: x = floor(cbrt(p) * 2^32) satisfies
x^3 <= p * 2^96 < (x + 1)^3, and y = floor(sqrt(n) * 2^30) satisfies
y^2 <= n * 2^60 < (y + 1)^2. The powers of two are whole limbs (96 = 8 * 12,
60 = 5 * 12), so p * 2^96 is the limb p after 8 zero limbs. Each constant's
proof is the schoolbook product with its carries written out, which this script
computes; the compiler checks every limb equation, so a script that is wrong
makes a proof that does not type-check, and a constant that is not the root
has no proof at all.

usage: gen-roots.py [--check] [src/lib.bats]   (--check: fail if the file differs)
"""
import math, sys

B = 4096
BEGIN = "(* BEGIN generated by scripts/gen-roots.py *)"
END = "(* END generated by scripts/gen-roots.py *)"


def limbs(n, count):
    out = []
    for _ in range(count):
        out.append(n % B)
        n //= B
    assert n == 0
    return out


def icbrt(n):
    lo, hi = 0, 1 << 40
    while lo < hi:
        mid = (lo + hi + 1) // 2
        if mid ** 3 <= n:
            lo = mid
        else:
            hi = mid - 1
    return lo


def primes(count):
    out, k = [], 2
    while len(out) < count:
        if all(k % q for q in out):
            out.append(k)
        k += 1
    return out


def product(a, b):
    """The limbs of a * b and the carry out of each column but the last
    (the last column's carry is the top limb)."""
    columns = len(a) + len(b) - 1
    result, carries, carry = [], [], 0
    for k in range(columns):
        total = carry + sum(a[i] * b[k - i] for i in range(len(a)) if 0 <= k - i < len(b))
        result.append(total % B)
        carry = total // B
        carries.append(carry)
    result.append(carry)
    return result, carries[:-1]


def add(a, b, carry_in):
    result, carries, carry = [], [], carry_in
    for i in range(len(a)):
        total = a[i] + b[i] + carry
        result.append(total % B)
        carry = total // B
        carries.append(carry)
    return result, carries


def csv(values):
    return ",".join(str(v) for v in values)


def relations():
    out = []
    # LIMB_SQUARE: s = x * x, x of 3 limbs, s of 6
    xs = [f"x{i}" for i in range(3)]
    ss = [f"s{i}" for i in range(6)]
    cs = [f"c{i}" for i in range(4)]
    eqs = []
    for k in range(5):
        terms = " + ".join(f"x{i}*x{k - i}" for i in range(3) if 0 <= k - i < 3)
        carry_in = f" + c{k - 1}" if k > 0 else ""
        out_side = f"s{k} + 4096*c{k}" if k < 4 else "s4 + 4096*s5"
        eqs.append(f"{terms}{carry_in} == {out_side}")
    out.append("""(* LIMB_SQUARE(x0, x1, x2, s0, ..., s5): s is x * x. A number is its limbs of
   12 bits, least significant first (4096 = 2 to the 12), so that a product of
   two limbs is under 2 to the 24 and every equation below stays far under the
   solver's 2 to the 29: x0 + 4096 * x1 + 4096^2 * x2 is x. Each constructor
   writes the schoolbook product column by column: the column's products and
   the carry in are its limb and 4096 times the carry out (a witness the
   caller gives); the carry out of the last column is the top limb. *)""")
    out.append("#pub dataprop LIMB_SQUARE(" + ",".join(["int"] * 9) + ") =")
    out.append("  | {" + ",".join(xs + ss + cs) + ":nat | "
               + "; ".join(f"{v} < 4096" for v in xs + ss) + ";\n      " + ";\n      ".join(eqs) + "}")
    out.append("    LIMB_SQUARE_mk(" + ",".join(xs + ss) + ")\n")
    # LIMB_MULTIPLY: y = s * x, s of 6 limbs, x of 3, y of 9
    ss = [f"s{i}" for i in range(6)]
    xs = [f"x{i}" for i in range(3)]
    ys = [f"y{i}" for i in range(9)]
    cs = [f"c{i}" for i in range(7)]
    eqs = []
    for k in range(8):
        terms = " + ".join(f"s{i}*x{k - i}" for i in range(6) if 0 <= k - i < 3)
        carry_in = f" + c{k - 1}" if k > 0 else ""
        out_side = f"y{k} + 4096*c{k}" if k < 7 else "y7 + 4096*y8"
        eqs.append(f"{terms}{carry_in} == {out_side}")
    out.append("(* LIMB_MULTIPLY(s0, ..., s5, x0, x1, x2, y0, ..., y8): y is s * x *)")
    out.append("#pub dataprop LIMB_MULTIPLY(" + ",".join(["int"] * 18) + ") =")
    out.append("  | {" + ",".join(ss + xs + ys + cs) + ":nat | "
               + "; ".join(f"{v} < 4096" for v in ss + xs + ys) + ";\n      " + ";\n      ".join(eqs) + "}")
    out.append("    LIMB_MULTIPLY_mk(" + ",".join(ss + xs + ys) + ")\n")
    # LIMB_CUBE
    out.append("(* LIMB_CUBE(x0, x1, x2, y0, ..., y8): y is x * x * x *)")
    out.append("#pub dataprop LIMB_CUBE(" + ",".join(["int"] * 12) + ") =")
    out.append("  | {x0,x1,x2,s0,s1,s2,s3,s4,s5,y0,y1,y2,y3,y4,y5,y6,y7,y8:nat}")
    out.append("    LIMB_CUBE_mk(x0,x1,x2,y0,y1,y2,y3,y4,y5,y6,y7,y8) of (")
    out.append("      LIMB_SQUARE(x0,x1,x2,s0,s1,s2,s3,s4,s5),")
    out.append("      LIMB_MULTIPLY(s0,s1,s2,s3,s4,s5,x0,x1,x2,y0,y1,y2,y3,y4,y5,y6,y7,y8))\n")
    # LIMB_ADD
    a = [f"a{i}" for i in range(9)]
    b = [f"b{i}" for i in range(9)]
    c = [f"c{i}" for i in range(9)]
    k = [f"k{i}" for i in range(9)]
    eqs = []
    for i in range(9):
        carry_in = "carry_in" if i == 0 else f"k{i - 1}"
        eqs.append(f"a{i} + b{i} + {carry_in} == c{i} + 4096*k{i}")
    out.append("""(* LIMB_ADD(a0, ..., a8, b0, ..., b8, carry_in, c0, ..., c8): c is a + b +
   carry_in, of 9 limbs with no carry out of the last (k8 is 0) *)""")
    out.append("#pub dataprop LIMB_ADD(" + ",".join(["int"] * 28) + ") =")
    out.append("  | {" + ",".join(a + b + c + k + ["carry_in"]) + ":nat | carry_in <= 1;\n      "
               + "; ".join(f"{v} < 4096" for v in a + b + c) + ";\n      "
               + ";\n      ".join(eqs) + "; k8 == 0}")
    out.append("    LIMB_ADD_mk(" + ",".join(a + b) + ",carry_in," + ",".join(c) + ")\n")
    # CUBE_ROOT_FRAC32
    xs = ["x0", "x1", "x2"]
    xp = ["xp0", "xp1", "xp2"]
    y = [f"y{i}" for i in range(9)]
    d = [f"d{i}" for i in range(9)]
    z = [f"z{i}" for i in range(9)]
    e = [f"e{i}" for i in range(9)]
    target = ",".join(["0"] * 8 + ["p"])
    out.append("""(* CUBE_ROOT_FRAC32(p, high, low): high:low (two 16-bit halves) is the first
   32 bits of the fractional part of the cube root of p, FIPS 180-4's
   definition of SHA-256's constants: with x = floor(cbrt(p) * 2 to the 32) =
   q * 2 to the 32 + high * 2 to the 16 + low (the root's integer part q is
   the part over 32 bits), x^3 <= p * 2 to the 96 < (x + 1)^3. The relation
   says x^3 + d = p * 2 to the 96 (d, a natural number, is the difference) and
   (x + 1)^3 = p * 2 to the 96 + e + 1; p * 2 to the 96 is the limb p after 8
   zero limbs. The first line of guards ties the limbs of x to high and low. *)""")
    out.append("#pub dataprop CUBE_ROOT_FRAC32(int,int,int) =")
    out.append("  | {" + ",".join(["p", "high", "low", "r", "u", "v", "q"] + xs + xp + y + d + z + e) + ":nat | p < 4096; high < 65536; low < 65536;\n      "
               + "; ".join(f"{v} < 4096" for v in xs + xp + y + d + z + e) + ";\n      "
               + "x0 + 4096*r == low; x1 == r + 16*u; u + 256*v == high; x2 == v + 256*q}")
    out.append("    CUBE_ROOT_FRAC32_mk(p,high,low) of (")
    out.append("      LIMB_CUBE(x0,x1,x2," + ",".join(y) + "),")
    out.append("      LIMB_ADD(" + ",".join(y) + "," + ",".join(d) + ",0," + target + "),")
    out.append("      LIMB_ADD(x0,x1,x2," + ",".join(["0"] * 15) + ",1,xp0,xp1,xp2," + ",".join(["0"] * 6) + "),")
    out.append("      LIMB_CUBE(xp0,xp1,xp2," + ",".join(z) + "),")
    out.append("      LIMB_ADD(" + target + "," + ",".join(e) + ",1," + ",".join(z) + "))\n")
    # SQUARE_ROOT_FRAC30
    ys = ["y0", "y1", "y2"]
    yp = ["yp0", "yp1", "yp2"]
    qs = [f"q{i}" for i in range(6)]
    ds = [f"d{i}" for i in range(6)]
    zs = [f"z{i}" for i in range(6)]
    es = [f"e{i}" for i in range(6)]
    pad = lambda v: ",".join(v + ["0"] * 3)
    target = ",".join(["0"] * 5 + ["n"] + ["0"] * 3)
    out.append("""(* SQUARE_ROOT_FRAC30(n, high, low): high:low (two 16-bit halves) is the
   integer part of 2 to the 30 times the square root of n, FIPS 180-4's
   definition of SHA-1's constants: with y = high * 2 to the 16 + low,
   y^2 <= n * 2 to the 60 < (y + 1)^2 (n * 2 to the 60 is the limb n after 5
   zero limbs). Written like CUBE_ROOT_FRAC32 on the 6 low limbs of LIMB_ADD. *)""")
    out.append("#pub dataprop SQUARE_ROOT_FRAC30(int,int,int) =")
    out.append("  | {" + ",".join(["n", "high", "low", "r", "u"] + ys + yp + qs + ds + zs + es) + ":nat | n < 4096; high < 65536; low < 65536;\n      "
               + "; ".join(f"{v} < 4096" for v in ys + yp + qs + ds + zs + es) + ";\n      "
               + "y0 + 4096*r == low; y1 == r + 16*u; u + 256*y2 == high}")
    out.append("    SQUARE_ROOT_FRAC30_mk(n,high,low) of (")
    out.append("      LIMB_SQUARE(y0,y1,y2," + ",".join(qs) + "),")
    out.append("      LIMB_ADD(" + pad(qs) + "," + pad(ds) + ",0," + target + "),")
    out.append("      LIMB_ADD(y0,y1,y2," + ",".join(["0"] * 15) + ",1,yp0,yp1,yp2," + ",".join(["0"] * 6) + "),")
    out.append("      LIMB_SQUARE(yp0,yp1,yp2," + ",".join(zs) + "),")
    out.append("      LIMB_ADD(" + target + "," + pad(es) + ",1," + pad(zs) + "))\n")
    return "\n".join(out)


def square_term(x, s, carries):
    return "LIMB_SQUARE_mk{" + csv(x + s + carries) + "}()"


def cube_term(x):
    s, square_carries = product(x, x)
    y, multiply_carries = product(s, x)
    term = ("LIMB_CUBE_mk{" + csv(x + s + y) + "}(" + square_term(x, s, square_carries)
            + ", LIMB_MULTIPLY_mk{" + csv(s + x + y + multiply_carries) + "}())")
    return term, y


def add_term(a, b, carry_in):
    c, carries = add(a, b, carry_in)
    return "LIMB_ADD_mk{" + csv(a + b + c + carries + [carry_in]) + "}()", c


def hexword(h, l):
    return f"0x{h:04x}, 0x{l:04x}"


def cube_root_proof(p):
    x = icbrt(p << 96)
    key = x % (1 << 32)
    high, low = key >> 16, key & 0xffff
    xl, xp = limbs(x, 3), limbs(x + 1, 3)
    target = p << 96
    assert x ** 3 <= target < (x + 1) ** 3
    y_term, y = cube_term(xl)
    z_term, z = cube_term(xp)
    d = limbs(target - x ** 3, 9)
    e = limbs((x + 1) ** 3 - target - 1, 9)
    bound = [0] * 8 + [p]
    low_add, low_sum = add_term(y, d, 0)
    inc_add, inc_sum = add_term(xl + [0] * 6, [0] * 9, 1)
    high_add, high_sum = add_term(bound, e, 1)
    assert low_sum == bound and inc_sum == xp + [0] * 6 and high_sum == z
    r, u = xl[1] % 16, xl[1] // 16
    v, q = xl[2] % 256, xl[2] // 256
    assert xl[0] + 4096 * r == low and u + 256 * v == high
    args = csv([p, high, low, r, u, v, q] + xl + xp + y + d + z + e)
    return (p, high, low, "CUBE_ROOT_FRAC32_mk{" + args + "}(\n    " + y_term + ",\n    " + low_add
            + ",\n    " + inc_add + ",\n    " + z_term + ",\n    " + high_add + ")")


def square_root_proof(n):
    y = math.isqrt(n << 60)
    high, low = y >> 16, y & 0xffff
    yl, yp = limbs(y, 3), limbs(y + 1, 3)
    target = n << 60
    assert y * y <= target < (y + 1) ** 2
    q, qc = product(yl, yl)
    z, zc = product(yp, yp)
    d = limbs(target - y * y, 6)
    e = limbs((y + 1) ** 2 - target - 1, 6)
    bound = [0] * 5 + [n]
    low_add, low_sum = add_term(q + [0] * 3, d + [0] * 3, 0)
    inc_add, inc_sum = add_term(yl + [0] * 6, [0] * 9, 1)
    high_add, high_sum = add_term(bound + [0] * 3, e + [0] * 3, 1)
    assert low_sum == bound + [0] * 3 and inc_sum == yp + [0] * 6 and high_sum == z + [0] * 3
    r, u = yl[1] % 16, yl[1] // 16
    assert yl[0] + 4096 * r == low and u + 256 * yl[2] == high
    args = csv([n, high, low, r, u] + yl + yp + q + d + z + e)
    return (n, high, low, "SQUARE_ROOT_FRAC30_mk{" + args + "}(\n    " + square_term(yl, q, qc) + ",\n    "
            + low_add + ",\n    " + inc_add + ",\n    " + square_term(yp, z, zc) + ",\n    " + high_add + ")")


def block():
    out = [BEGIN, "", relations()]
    out.append("""(* The proofs of the constants: each is the proof of its table entry's word
   (the annotation says which), written out by scripts/gen-roots.py with the
   carries of the schoolbook products as the constructors' arguments. *)""")
    for p in primes(64):
        n, high, low, term = cube_root_proof(p)
        out.append(f"prfn cube_root_of_{p} (): CUBE_ROOT_FRAC32({p}, {hexword(high, low)}) =\n  {term}\n")
    for n in (2, 3, 5, 10):
        n, high, low, term = square_root_proof(n)
        out.append(f"prfn square_root_of_{n} (): SQUARE_ROOT_FRAC30({n}, {hexword(high, low)}) =\n  {term}\n")
    out.append(END)
    return "\n".join(out)


def main():
    args = [a for a in sys.argv[1:] if a != "--check"]
    path = args[0] if args else "src/lib.bats"
    text = open(path).read()
    start, stop = text.index(BEGIN), text.index(END) + len(END)
    new = text[:start] + block() + text[stop:]
    if "--check" in sys.argv:
        if new != text:
            sys.exit("src/lib.bats is not what scripts/gen-roots.py writes")
    else:
        open(path, "w").write(new)


if __name__ == "__main__":
    main()
